type Action =
  | { type: "insert"; text: string }
  | { type: "delete"; count: number }
  | { type: "undo" }
  | { type: "redo" };

interface EditorState {
  past: string[];
  present: string;
  future: string[];
}

function assertNever(x: never): never {
  throw new Error("Action tidak dikenal: " + JSON.stringify(x));
}

function commit(state: EditorState, next: string): EditorState {
  if (next === state.present) return state;
  return { past: [...state.past, state.present], present: next, future: [] };
}

function reducer(state: EditorState, action: Action): EditorState {
  switch (action.type) {
    case "insert":
      return commit(state, state.present + action.text);
    case "delete": {
      if (action.count <= 0) return state;
      const keep = Math.max(0, state.present.length - action.count);
      return commit(state, state.present.slice(0, keep));
    }
    case "undo": {
      if (state.past.length === 0) return state;
      const previous = state.past[state.past.length - 1];
      return { past: state.past.slice(0, -1), present: previous, future: [state.present, ...state.future] };
    }
    case "redo": {
      if (state.future.length === 0) return state;
      const [next, ...rest] = state.future;
      return { past: [...state.past, state.present], present: next, future: rest };
    }
    default:
      return assertNever(action);
  }
}

function runEditor(actions: Action[]): { text: string; canUndo: boolean; canRedo: boolean } {
  let state: EditorState = { past: [], present: "", future: [] };
  for (const action of actions) state = reducer(state, action);
  return { text: state.present, canUndo: state.past.length > 0, canRedo: state.future.length > 0 };
}

